import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

        cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define VECTOR_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_DIM + ty;
    int col_start = bx * TILE_DIM;

    float Cvec[VECTOR_SIZE] = {0.0f};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load a tile of A and B into shared memory
        if (row < N && (t * TILE_DIM + tx) < N) {
            As[ty][tx] = A[row * N + (t * TILE_DIM + tx)];
        } else {
            As[ty][tx] = 0.0f;
        }

        for (int v = 0; v < VECTOR_SIZE; ++v) {
            int b_col = col_start + tx * VECTOR_SIZE + v;
            if ((t * TILE_DIM + ty) < N && b_col < N) {
                Bs[ty][tx*VECTOR_SIZE+v] = B[(t * TILE_DIM + ty) * N + b_col];
            } else {
                Bs[ty][tx*VECTOR_SIZE+v] = 0.0f;
            }
        }
        __syncthreads();

        // Compute partial results
        for (int k = 0; k < TILE_DIM; ++k) {
            float a_val = As[ty][k];
            for (int v = 0; v < VECTOR_SIZE; v++) {
                Cvec[v] += a_val * Bs[k][tx * VECTOR_SIZE + v];
            }
        }
        __syncthreads();
    }

    // Write the results to global memory
    for (int v = 0; v < VECTOR_SIZE; v++) {
        int col = col_start + tx * VECTOR_SIZE + v;
        if (row < N && col < N) {
            C[row * N + col] = Cvec[v];
        }
    }
}

torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions are incompatible for multiplication");

    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());

    dim3 threadsPerBlock(TILE_DIM / VECTOR_SIZE, TILE_DIM);
    dim3 numBlocks((N + TILE_DIM - 1) / TILE_DIM, (N + TILE_DIM - 1) / TILE_DIM);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
